def button(href,text,cls=''):return f'<a class="button {cls}" href="{href}">{text}{icon("arrow")}</a>'
def card(p):
 action=f'<a class="quick-add" href="/products/{p["handle"]}/" aria-label="Choose options for {e(p["title"])}">{icon("arrow")}</a>' if len(p['variants'])>1 or p['category']=='1-2-gallon-jugs' else f'<button class="quick-add" data-add="{p["handle"]}" aria-label="Add {e(p["title"])} to bag">+</button>'
 return f'<article class="product-card" data-product="{p["handle"]}"><div class="card-image" style="background:{p["photoBackground"]}"><a href="/products/{p["handle"]}/"><img src="{p["images"][0]}" alt="{e(p["title"])}" loading="lazy"></a><span class="card-tag">{e(p["flavour"])}</span>{action}</div><div class="card-heading"><h3><a href="/products/{p["handle"]}/">{e(p["title"])}</a></h3><span class="price">{price(p)}</span></div><p class="card-ingredients">{e(' · '.join(p['ingredients']) if p['ingredients'] else p['flavour'])}</p></article>'
